#import <XCTest/XCTest.h>
#import "DNSKitTests.h"
#import "../DNSKit/Crypto/ASN1Utils.h"
#import "../DNSKit/Extensions/NSData+HexString.h"
@import DNSKit;

@interface ASN1UtilsTests : XCTestCase

@end

@implementation ASN1UtilsTests

- (void) setUp {
    // Put setup code here. This method is called before the invocation of each test method in the class.
}

- (void) tearDown {
    // Put teardown code here. This method is called after the invocation of each test method in the class.
}

- (void) testPKCS1ForRSAKey {
    NSData * modulus = [NSData fromHexString:@""];
    uint32_t exponent = 65537;

    NSData * pkcs1 = [ASN1Utils pkcs1RSAPubkey:exponent exponentLength:3 modulus:modulus];
    XCTAssertStringEqual(pkcs1.hexString, @"");
}

- (void) testPKCS1ForECSignature {
    NSData * signature = [NSData fromHexString:@"00F06B223B16D058C6AEA36E9AC04F2A069B1A1101349E045159A39F0704948B905D9F1B41507B5E6008B14899DB70CE1D8E11F61834C08E7D2D2AEDEACB42C7"];

    NSData * pkcs1 = [ASN1Utils pkcs1Signature:signature algorithm:DNSSECAlgorithmECDSAP256_SHA256];
    XCTAssertStringEqual(pkcs1.hexString, @"3045022000f06b223b16d058c6aea36e9ac04f2a069b1a1101349e045159a39f0704948b022100905d9f1b41507b5e6008b14899db70ce1d8e11f61834c08e7d2d2aedeacb42c7");
}

@end
